SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS boh_operativo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE boh_operativo;
SET FOREIGN_KEY_CHECKS=0;
ON DUPLICATE KEY UPDATE codigo_interno=VALUES(codigo_interno), nombre=VALUES(nombre), unidad_medida=VALUES(unidad_medida), categoria=VALUES(categoria), formato=VALUES(formato), costo_unitario=VALUES(costo_unitario), stock_actual=VALUES(stock_actual), areas_destino=VALUES(areas_destino), activo=VALUES(activo), ultima_actualizacion=VALUES(ultima_actualizacion);
UPDATE insumos SET costo_est = costo_unitario WHERE costo_est IS NULL OR costo_est <> costo_unitario;
TRUNCATE TABLE recetas;
 Cuando todos los ingredientes estén blandos y la sopa haya espesado, dejar reposar. Procesar, añade la leche de coco. Deja hervir a fuego bajo por 5 minutos más, ajusta la sal y añade el toque final de limón antes de servir.PRESENTACIÓN: Azafate olla de bruja. Mantener a 65°C.', '[{"n": "Leche De Coco", "detalle": "enlatada espesa", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 3000.0, "und": "ml", "costo": 46892.97}, {"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 350.0, "und": "ml", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Ñame", "detalle": "espino", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 378.632}, {"n": "Leche De Coco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 3000.0, "und": "ml", "costo": 46892.97}, {"n": "Platano Maduro", "detalle": "bine maduro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 388.188}, {"n": "Ajo", "detalle": "pasta", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 1073.028}, {"n": "Cebolla Cabezona", "detalle": "blanca, brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 827.112}, {"n": "Frijol Cabeza Negra", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3000.0, "und": "gr", "costo": 21484.95}, {"n": "Aji Dulce", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 740.368}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'CONSUME PESCADO', 100, NULL, '1. Lava muy bien las cabezas y huesos de pescado, retirando las branquias para evitar sabores amargos. 2. Sofríe ligeramente los vegetales picados en una olla con aceite durante 3 a 5 minutos.
 Añade el pescado, el agua, las hierbas aromáticas y el laurel a la olla. 3. Cocina a fuego medio-bajo entre 30 y 45 minutos, retirando la espuma blanca de la superficie con una espumadera. Retira del fuego y pasa el caldo por un colador fino o tela limpia para eliminar impurezas y restos sólidos. Ajusta la sal, agregar el chorrito de vino y una concha de limon limpia de bagazo y sirve caliente con cilantro picado y gotas de limón.PRESENTACIÓN: Mantener a 65°C.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Fondo De Pescado", "detalle": "fondo de pescado", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15000.0, "und": "gr", "costo": 19116.71688}, {"n": "Cebolla Cabezona", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 1240.668}, {"n": "Apio", "detalle": "brunosie", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 727.203}, {"n": "Zanahoria", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 500.112}, {"n": "Ajo", "detalle": "pasta", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 70.0, "und": "gr", "costo": 751.1196}, {"n": "Puerro", "detalle": "Brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 1432.444}, {"n": "Limon", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 600.0, "und": "gr", "costo": 4079.952}, {"n": "Vino Blanco", "detalle": "de cocina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 700.0, "und": "ml", "costo": 13170.213}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'CREMA DE MAZORCA', 100, NULL, '1. Licúa 500g de maíz dulce congelado con 3 tazas de leche hasta obtener una mezcla homogénea. 2. Caramelizar las cebollas en margarina. Cuela la mezcla sobre una olla (opcional, si prefieres una textura más fina) y calienta a fuego medio. Rehogar con el fonde de vegetales. En media taza de leche fría, disuelve 1 cucharada de fécula de maíz y 1 cucharada de harina precocida de maíz amarillo para choclo para evitar grumos. 3. Vierte la mezcla de harinas en la olla revolviendo constantemente para que no se pegue al fondo. 4. Agrega una cucharada de mantequilla, sal, pimienta y una pizca de azúcar para resaltar el dulce del maíz. 5. Cocina a fuego bajo durante 8 a 10 minutos hasta que la crema espese y la harina precocida esté bien cocida.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 20000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "ml", "costo": 52.23795}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Maiz Dulce", "detalle": "precongelado", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 6000.0, "und": "gr", "costo": 89677.56}, {"n": "Harina De Maiz", "detalle": "precocida/ amarilla", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 400.0, "und": "gr", "costo": 1226.284}, {"n": "Cebolla Cabezona", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 827.112}, {"n": "Margarina", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 2957.982}, {"n": "Fecula", "detalle": "maicena", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 170.0, "und": "gr", "costo": 0.0}, {"n": "Fondo Vegetal", "detalle": null, "presentacion": 20000.0, "presentacion_unidad": "ml", "cant": 15000.0, "und": "ml", "costo": 1625.204298}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'CREMA DE ZANAHORIA Y JENGIBRE', 100, NULL, '1. Sofríe la cebolla en una olla con mantequilla o aceite de oliva hasta que esté transparente.2. Agrega las zanahorias y una cucharadita de jengibre fresco rallado, revolviendo por 2 minutos para resaltar los aromas. 3. Cubre los ingredientes con fondo corto o agua y cocina a fuego medio hasta que las zanahorias estén completamente blandas.
 Licúa la preparación hasta obtener una textura suave y sedosa, devolviéndola luego a la olla.4. Salpimenta al gusto y deja hervir a fuego bajo por 3 minutos para integrar los sabores cítricos.PRESENTACIÓN: Azafate medio con rejilla para drenar. Proteína en fila o distribución uniforme con salsa napando. Mantener a 65°C.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Zanahoria", "detalle": "enteras", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5000.0, "und": "gr", "costo": 8335.2}, {"n": "Pulpa De Naranja", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5000.0, "und": "gr", "costo": 41706.85}, {"n": "Naranja", "detalle": "rallaura", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 400.0, "und": "gr", "costo": 1737.82}, {"n": "Jengibre", "detalle": "rallado", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 1437.716}, {"n": "Cebolla Cabezona", "detalle": "Brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 1240.668}, {"n": "Puerro", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 2148.666}, {"n": "Comino", "detalle": "semillas tostadas", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 40.0, "und": "gr", "costo": 2299.9064}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'SOPA DE POLLO Y PASTA', 100, NULL, '1. En una olla grande con agua, pon a cocinar el pollo junto con la cebolla, el ajo y el apio a fuego medio durante 20-25 minutos. Retira la espuma que se forma en la superficie con una espumadera para que el caldo quede claro. 2. Agrega la zanahoria y las papas a la olla. Cocina por 10 minutos más hasta que empiecen a ablandar. 3. Incorpora la pasta directamente al caldo. Si usas fideos delgados (cabello de ángel), solo necesitarán de 3 a 5 minutos; si es pasta gruesa, revisa el tiempo del empaque (usualmente 8-10 min). 4. retira el pollo por un momento, desméchalao en trozos medianos y devuélvela a la olla. 5. Ajusta la sal y la pimienta. Apaga el fuego y añade el cilantro fresco picado justo antes de servir. PRESENTACIÓN: Azafate medio con rejilla para drenar. Proteína en fila o distribución uniforme con salsa napando. Mantener a 65°C.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Muslo de Pollo", "detalle": "pierna pernil", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5000.0, "und": "gr", "costo": 29857.45}, {"n": "Fideo", "detalle": "cebello de angeL o FARFALLE", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 250.0, "und": "gr", "costo": 1756.72}, {"n": "Papa", "detalle": "cubos", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 400.0, "und": "gr", "costo": 1393.276}, {"n": "Zanahoria", "detalle": "cubos", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 250.0, "und": "gr", "costo": 416.76}, {"n": "Apio", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 250.0, "und": "gr", "costo": 606.0025}, {"n": "Cebolla Cabezona", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 250.0, "und": "gr", "costo": 1033.89}, {"n": "Ajo", "detalle": "pasta", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 40.0, "und": "ml", "costo": 429.2112}, {"n": "Cilantro", "detalle": "picado finamente", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 911.376}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'CREMA DE ALMEJAS', 100, NULL, '1. En una olla grande a fuego medio, cocina el tocino hasta que esté crujiente. Retira los trozos y reserva 2 cucharadas de la grasa en la olla. 2. Agrega la cebolla y el apio a la grasa del tocino. Cocina hasta que la cebolla esté transparente (5-7 minutos). anadir las conchas y rehogar con vino. retirar las cocnhas y reservar. 3. Espolvorea la harina sobre los vegetales y cocina por 1-2 minutos revolviendo constantemente para que no se queme; esto espesará la crema. 4. Vierte lentamente el fumet, la crema de leche, la hoja de laurel y el tomillo y batir. Añade las papas y deja hervir suavemente por 15-20 minutos o hasta que estén tiernas y comeincen a desintegrarse. Ajusta la sal y pimienta. PRESENTACIÓN: Azafate de bruja Proteína. Mantener a 65°C.', '[{"n": "Ajo", "detalle": "picado fino", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 1073.028}, {"n": "Vino Blanco", "detalle": "seco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 500.0, "und": "gr", "costo": 9407.295}, {"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 3134.277}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Almeja", "detalle": "concha blanca", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3500.0, "und": "gr", "costo": 59500.0}, {"n": "Tocineta", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1000.0, "und": "gr", "costo": 31887.6}, {"n": "Papa", "detalle": "cubos", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1500.0, "und": "gr", "costo": 5224.785}, {"n": "Laurel", "detalle": "entero", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 20.0, "und": "gr", "costo": 1714.1792}, {"n": "Tomillo Fresco", "detalle": "seco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 30.0, "und": "gr", "costo": 1323.5301}, {"n": "margarina", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 60.0, "und": "gr", "costo": 591.5964}, {"n": "Fondo De Pescado", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15000.0, "und": "gr", "costo": 19116.71688}, {"n": "Maicena", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 80.0, "und": "gr", "costo": 409.1616}, {"n": "Cebolla Cabezona", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 827.112}, {"n": "Apio", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 484.802}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'CONSUME DE VERDURAS', 100, NULL, '1. Lava bien todos los vegetales y córtalos en trozos medianos. 2. En una olla con un chorrito de aceite, saltea la cebolla, el puerro y el ajo a fuego medio durante 3 minutos hasta que suelten su aroma, sin dejar que se doren demasiado. 3. Agrega el resto de los vegetales (zanahoria, apio) y el agua fría. El agua fría ayuda a que el sabor salga gradualmente de las fibras vegetales. 4. Añade el laurel, el perejil y los granos de pimienta. 5. Lleva a ebullición y, en cuanto hierva, baja el fuego al mínimo. Cocina tapado durante 45 a 60 minutos. Filtrado: Retira del fuego y pasa el caldo por un colador fino para que quede ligeramehte transparente. Agrega la sal solo al final para controlar mejor el punto de sabor tras la reducción.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Zanahoria", "detalle": "cubos pequenos", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1000.0, "und": "gr", "costo": 1667.04}, {"n": "Apio", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1000.0, "und": "gr", "costo": 2424.01}, {"n": "Cebolla Cabezona", "detalle": "brunopise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1000.0, "und": "gr", "costo": 4135.56}, {"n": "Jengibre", "detalle": "rallado", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 60.0, "und": "gr", "costo": 862.6296}, {"n": "Laurel", "detalle": "resco, e ntero", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15.0, "und": "gr", "costo": 1285.6344}, {"n": "Perejil Fresco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 120.0, "und": "gr", "costo": 1018.6908}, {"n": "Puerro", "detalle": "brunoise", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 900.0, "und": "ml", "costo": 6445.998}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'CREMA DE CEBOLLA', 100, NULL, '1. En una cacerola de fondo grueso, derrite la mantequilla a fuego mínimo. Agrega las cebollas con una pizca de sal. El objetivo no es dorarlas rápido, sino "sudarlas" tapadas durante 30-40 minutos hasta que alcancen un color ámbar profundo y uniforme, caramelizando sus propios azúcares de forma natural. 2. Sube ligeramente el fuego y vierte el vino blanco para desprender los jugos caramelizados del fondo de la olla. Deja reducir hasta que el alcohol se evapore casi por completo. 3. Cubre las cebollas con el caldo de ave clarificado. Añade el tomillo atado (bouquet garni) y cocina a fuego muy lento por 20 minutos. 4. Retira el tomillo. Pasa la mezcla a una licuadora de alta velocidad. Procesa a máxima potencia hasta que la fricción cree una emulsión completamente lisa. 5. Devuelve la crema al fuego mínimo y añade la crema de leche. No dejes que hierva; solo busca que se integre. Ajusta la sazón con pimienta blanca.', '[{"n": "Cebolla Cabezona", "detalle": "juliana o brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5000.0, "und": "gr", "costo": 20677.8}, {"n": "Puerro", "detalle": "juliana o brunoise", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 2000.0, "und": "gr", "costo": 14324.44}, {"n": "Ajo", "detalle": "picado fino", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 1073.028}, {"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 350.0, "und": "ml", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Laurel", "detalle": "entero", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 14.0, "und": "gr", "costo": 1199.92544}, {"n": "Vino Blanco", "detalle": "seco, de cocina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 600.0, "und": "gr", "costo": 11288.754}, {"n": "Tomillo Fresco", "detalle": "fresco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 40.0, "und": "gr", "costo": 1764.7068}, {"n": "Margarina", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 500.0, "und": "gr", "costo": 4929.97}, {"n": "Crema De Leche", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 1000.0, "und": "ml", "costo": 14000.0}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'POTAJE DE PAPAS', 100, NULL, '1. En una olla a fuego medio-bajo, carameliza las cebollas con la margarina hasta que estén doradas y dulces. 2. Agrega las papas en cubos y el bouquet de aromáticos. Sofreír por un par de minutos para sellar el sabor y luego rehogar cubriendo todo con el fondo de ave caliente. 3. Cocina a fuego lento hasta que la papa esté completamente blanda, casi desintegrándose al tacto. 4. Retira el bouquet de hierbas, procesa la mezcla (licuadora o mixer) junto con la crema hasta obtener una emulsión lisa y rectifica sazón.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Papa Sabanera", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 9000.0, "und": "gr", "costo": 32035.68}, {"n": "Puerro", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 2000.0, "und": "gr", "costo": 14324.44}, {"n": "Fondo De Ave", "detalle": "clarificada", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 15000.0, "und": "ml", "costo": 26755.3974}, {"n": "Cebolla Larga", "detalle": "biselados. Solo blanco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1000.0, "und": "gr", "costo": 5877.8}, {"n": "Crema de leche", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 1000.0, "und": "ml", "costo": 14000.0}, {"n": "Oregano Fresco", "detalle": "fresco, bouette", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 40.0, "und": "gr", "costo": 1643.68}]'),
('Almuerzo', 'SOPAS Y CREMAS', 'SOPA COREANA DE CARNE', 100, NULL, '1. hacer el Caldo Base (Umami) en una olla con agua fría, coloca una pieza de carne junto a la cebolla larga, rodajas gruesas de jengibre y pimienta en grano. Cocina a fuego lento, espumando constantemente para mantener la claridad, hasta que la carne esté tierna. 2. Retira la carne, deja enfriar y desméchala finamente. Alíñala en un tazón aparte con un poco de aceite de sésamo tostado, sal y una pizca de ajo picado para que resalte su sabor. 3. Cuela el caldo para eliminar los sólidos y aromatízalo con un chorrito de salsa de soya clara (o salsa de pescado para más umami) y sal. Mantén el caldo muy caliente pero sin hervir fuerte para no enturbiarlo.3. Corta los fideos por la mitad, sosten los fideos en agua fria por unos minutos hasta que suavicen un poco. 4. En una sartén pequeña, tuesta las semillas de sésamo a fuego bajo hasta que huelan a nuez y doren ligeramente y pulverizar. Corta la cebolla larga en rodajas muy finas 4. Añade la carne desmechada, los brotes de soya , los fideos y la cebolla larga. Termina con un chorrito de aceite de sésamo tostado.', '[{"n": "Aceite Vegetal", "detalle": "neutro", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3656.6565}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 130.0, "und": "gr", "costo": 372.424}, {"n": "Pimienta", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 18.0, "und": "gr", "costo": 1425.96432}, {"n": "Ajo", "detalle": "picado finamente", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 1073.028}, {"n": "Semillas de Sesamo", "detalle": "blanco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 150.0, "und": "gr", "costo": 4537.815}, {"n": "Jengibre", "detalle": "fresco, pajilla", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 100.0, "und": "gr", "costo": 