INSERT INTO recetas (servicio, categoria, nombre, rinde, alergenos, procedimiento, ingredientes) VALUES
('Almuerzo', 'SOPAS Y CREMAS', 'SANCOCHO DE CARNE', 100, NULL, 'Cocinar costilla en agua con cebolla, ajo y sal 1h espumando. Agregar yuca y plátano 20min. Añadir papas y mazorca 15min más hasta tiernizar. | PRESENTACIÓN: Servir en samovar hondo con cucharón. Mantener carne y tubérculos sumergidos. Cilantro fresco picado en recipiente aparte. Ají en salsera lateral.', '[{"n": "Costilla De Res", "detalle": "troceada 5cm, con hueso", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3000.0, "und": "gr", "costo": 82980.0}, {"n": "Yuca", "detalle": "pelada, trozos 4cm", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1300.0, "und": "gr", "costo": 3830.281}, {"n": "Papa Criolla", "detalle": "entera, sin pelar", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1300.0, "und": "gr", "costo": 12049.31}, {"n": "Papa Sabanera", "detalle": "cubos 5cm", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1300.0, "und": "gr", "costo": 4627.376}, {"n": "Platano Verde", "detalle": "rodajas 3cm diagonal", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 600.0, "und": "gr", "costo": 2500.134}, {"n": "Mazorca", "detalle": "rodajas 4cm", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 1200.0, "und": "gr", "costo": 5819.556}, {"n": "Cebolla Larga", "detalle": "entera, atada", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 400.0, "und": "gr", "costo": 2351.12}, {"n": "Cilantro", "detalle": "atado entero + chiffonade", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 140.0, "und": "gr", "costo": 1275.9264}, {"n": "Ajo", "detalle": "machacado", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 50.0, "und": "gr", "costo": 536.514}, {"n": "Comino", "detalle": "molido", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15.0, "und": "gr", "costo": 862.4649}, {"n": "Sal", "detalle": "fina", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 150.0, "und": "gr", "costo":