('Almuerzo', 'PROTEINAS - PESCADOS', 'ARROZ A LA MARINERA', 100, NULL, 'paella al estio latinoamericano con mariscos, chorizos y pollo. Arroz brillante con azafran (carmencita) guisantes, pimentos morrones', '[{"n": "Arroz", "detalle": "blanco, parbolizado", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 6000.0, "und": "gr", "costo": 14544.06}, {"n": "Pechuga De Pollo", "detalle": "cubos pequenos", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3800.0, "und": "gr", "costo": 37338.952}, {"n": "Chorizo Campesino", "detalle": "2000", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 2500.0, "und": "gr", "costo": 61165.14}, {"n": "Camaron", "detalle": "limpio", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3500.0, "und": "gr", "costo": 94472.035}, {"n": "Calamar Pota", "detalle": "limpio, tiras", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3200.0, "und": "gr", "costo": 43089.568}, {"n": "Mejillon", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 3000.0, "und": "gr", "costo": 18869.85}, {"n": "Cebolla Cabezona", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 2500.0, "und": "gr", "costo": 10338.9}, {"n": "Pimenton Rojo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 2500.0, "und": "gr", "costo": 21381.475}, {"n": "Ajo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 350.0, "und": "gr", "costo": 3755.598}, {"n": "Tomate", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 4000.0, "und": "gr", "costo": 25953.48}, {"n": "Fondo De Pescado", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 8000.0, "und": "ml", "costo": 10195.58234}, {"n": "Sazonador De Paella", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 420.0, "und": "gr", "costo": 135786.0}, {"n": "Habichuela", "detalle": null, "presentacion": 1