INSERT INTO recetas (servicio, categoria, nombre, rinde, alergenos, procedimiento, ingredientes) VALUES
('Almuerzo', 'ADEREZOS', 'Aderezo Cebolla Dulce', 50, NULL, '1.Trocear la cebolla en plumas,mezclar con el azúcar y el vinagre y hervir por 3 minutos a fuego medio.2.Enfriar,reservar,procesar la mezcla y pasar por tamiz.3.Agregar el resto de las especias y emulsionar con los aceites.4.Aromatizar al final con unas gotas de aceite de sésamo y rectificar el sabor con sal y pimienta.', '[{"n": "Cebolla Morada", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 500.0, "und": "gr", "costo": 2654.145}, {"n": "Miel", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 30.0, "und": "gr", "costo": 503.1072}, {"n": "Vinagre Blanco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 200.0, "und": "ml", "costo": 579.9845}, {"n": "Aceite Vegetal", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 200.0, "und": "ml", "costo": 2089.518}, {"n": "Sal", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 30.0, "und": "gr", "costo": 85.944}, {"n": "Vinagre Vino Tinto", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 200.0, "und": "ml", "costo": 3432.0}, {"n": "Azucar", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 60.0, "und": "gr", "costo": 170.2548}, {"n": "Cebolla En Polvo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15.0, "und": "gr", "costo": 495.0}, {"n": "Ajo El Polvo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15.0, "und": "gr", "costo": 225.0}, {"n": "Aceite Ajonjolí", "detalle": null, "presentacion": 100.0, "presentacion_unidad": "ml", "cant": 10.0, "und": "ml", "costo": 0}, {"n": "Paprika", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5.0, "und": "gr", "costo": 336.1346}]'),
('Almuerzo', 'ADEREZOS', 'VINAGRETA FRESA- BALSAMICO', 50, NULL, '1. Lavar,desinfectar y trocear las fresas.2.En una olla pequeña,poner a fuego medio las fresas con el vinagre balsámico y la miel por 5 minutos hasta que la fruta suavice;enfriar y reservar.3.Colocar la mezcla fría en la licuadora junto con la mostaza,el ajo,la albahaca,la sal y la pimienta;procesar hasta obtener un puré fino.4.Sin dejar de licuar a velocidad baja,incorporar el aceite de oliva en forma de hilo delgado hasta lograr una emulsión estable.5.Pasar por un tamiz fino si se desea una textura más delicada.', '[{"n": "Aceite Oliva", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 200.0, "und": "ml", "costo": 9000.0}, {"n": "Vinagre Balsamico", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 500.0, "und": "ml", "costo": 11248.275}, {"n": "Mostaza", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 60.0, "und": "gr", "costo": 874.8504878}, {"n": "Miel", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 150.0, "und": "gr", "costo": 2515.536}, {"n": "Fresa", "detalle": "maduras", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 3838.737}, {"n": "Albahaca", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15.0, "und": "gr", "costo": 420.25605}, {"n": "Limon", "detalle": "ralladura", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5.0, "und": "gr", "costo": 0}, {"n": "Pimienta Negra", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 10.0, "und": "gr", "costo": 792.2024}]'),
('Almuerzo', 'ADEREZOS', 'VINAGRETA ITALIANA', 50, NULL, '1.En un bol grande o licuadora,mezclar el vinagre,el agua,la miel,la mostaza y todos los ingredientes secos (especias y hierbas).2.Batir vigorosamente para que la sal y el azúcar se disuelvan completamente en el vinagre.3.Incorporar el aceite en un hilo delgado y constante mientras se sigue batiendo o licuando a velocidad media hasta lograr una emulsión homogénea.4.Trasvasar a un recipiente,tapar y dejar reposar al menos 12 horas para que las hierbas secas se hidraten y liberen su aroma.', '[{"n": "Aceite Oliva", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 500.0, "und": "gr", "costo": 22500.0}, {"n": "Vinagre Vino Tinto", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 250.0, "und": "gr", "costo": 4290.0}, {"n": "Mostaza", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 30.0, "und": "gr", "costo": 437.4252439}, {"n": "Oregano Seco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 10.0, "und": "gr", "costo": 300.1283}, {"n": "Tomillo Seco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 10.0, "und": "gr", "costo": 420.1681}, {"n": "Perejil Fresco", "detalle": "picado finamente", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 10.0, "und": "gr", "costo": 84.8909}, {"n": "Ajo El Polvo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5.0, "und": "gr", "costo": 75.0}, {"n": "Cebolla En Polvo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5.0, "und": "gr", "costo": 165.0}, {"n": "Parmesano", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 50.0, "und": "gr", "costo": 2740.026}, {"n": "Azucar", "detalle": "blanca", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 40.0, "und": "ml", "costo": 113.5032}, {"n": "Paprika", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 3.0, "und": "ml", "costo": 201.68076}, {"n": "Albahaca Seca", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5.0, "und": "gr", "costo": 145.2088}]'),
('Almuerzo', 'ADEREZOS', 'VINAGRETA CHOCO BALSAMICO', 50, NULL, '1.En una olla pequeña a fuego mínimo,calentar el vinagre con la miel y el cacao en polvo,batiendo constantemente con un batidor de globo hasta que no queden grumos y el cacao se disuelva;no dejar que hierva.2.Retirar del fuego y dejar enfriar completamente.3.En un bol,mezclar la base de chocolate y vinagre con la mostaza,la sal y la pimienta.4.Incorporar el aceite de oliva en un hilo delgado mientras se bate vigorosamente hasta lograr una emulsión sedosa y brillante.', '[{"n": "Vinagre Balsamico", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 600.0, "und": "ml", "costo": 13497.93}, {"n": "Cacao", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 40.0, "und": "gr", "costo": 2352.9412}, {"n": "Miel", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 60.0, "und": "gr", "costo": 0}, {"n": "Sal", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 20.0, "und": "gr", "costo": 57.296}, {"n": "Azucar", "detalle": "blanca", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 20.0, "und": "gr", "costo": 56.7516}, {"n": "Pimienta Blanca", "detalle": "molida", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 26.0, "und": "gr", "costo": 2621.84416}, {"n": "Aceite Vegetal", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 300.0, "und": "ml", "costo": 3134.277}, {"n": "Canela", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 3.0, "und": "ml", "costo": 0}, {"n": "Naranja", "detalle": "ralladura de cascara", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 5.0, "und": "gr", "costo": 21.72275}]'),
('Almuerzo', 'ADEREZOS', 'VINAGRETA DE COROZO Y COCO', 50, NULL, 'Calienta ligeramente el vinagre e incorpora pulpa de corozo, deja infusionar y reposar hasta intensificar color y acidez frutal 2. Procesa la mezcla y cuela para obtener base lisa y brillante 3. Incorpora miel mostaza ajo sal y pimienta y mezcla hasta homogenizar 4. Añade aceite de coco en hilo fino emulsionando hasta obtener vinagreta ligera y estable de color rojizo brillante 5. Ajusta acidez y sazón manteniendo textura fluida no espesa | PRESENTACION: Mantiene refrigerada ≤4°C, agitar antes del servicio para recuperar emulsión y brillo uniforme', '[{"n": "Corozo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 700.0, "und": "ml", "costo": 6943.867}, {"n": "Vinagre Blanco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 800.0, "und": "ml", "costo": 2319.938}, {"n": "Aceite De Coco", "detalle": "o escencia de coco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 13647.4104}, {"n": "Azucar", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 567.516}, {"n": "Mostaza", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 25.0, "und": "gr", "costo": 364.5210366}]'),
('Almuerzo', 'ADEREZOS', 'Aderezo Mexicano', 50, NULL, '1. Procesa jalapeño cilantro ajo limón y comino hasta mezcla homogénea 2. Incorpora mayonesa crema agria y aceite 3. Ajusta sal y pimienta y refrigera ≤4°C', '[{"n": "Mayonesa", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 400.0, "und": "gr", "costo": 18904.696}, {"n": "Suero", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 400.0, "und": "gr", "costo": 8227.98}, {"n": "Jalapeno", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 200.0, "und": "gr", "costo": 2800.0}, {"n": "Cilantro", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 40.0, "und": "gr", "costo": 364.5504}, {"n": "Salsa De Aji", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 65.0, "und": "ml", "costo": 916.49155}, {"n": "Comino", "detalle": "semilla, molido", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 8.0, "und": "gr", "costo": 459.98128}, {"n": "Oregano Seco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 10.0, "und": "gr", "costo": 300.1283}, {"n": "Paprika", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 10.0, "und": "ml", "costo": 672.2692}, {"n": "Limon", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 200.0, "und": "ml", "costo": 1359.984}, {"n": "Ajo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 25.0, "und": "gr", "costo": 268.257}, {"n": "Cebolla En Polvo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 20.0, "und": "gr", "costo": 660.0}]'),
('Almuerzo', 'ADEREZOS', 'VINAGRETA DE MARACUYA', 50, NULL, '1. Calienta ligeramente el vinagre e incorpora jengibre fresco laminado, deja infusionar y reposar hasta obtener aroma cítrico y picante balanceado 2. Mezcla la infusión colada con pulpa de maracuyá miel mostaza ajo sal y pimienta hasta homogenizar 3. Incorpora aceite vegetal en hilo fino emulsionando hasta obtener vinagreta ligera brillante y estable 4. Ajusta acidez dulzor y sazón manteniendo textura fluida y fresca | PRESENTACION: Mantiene refrigerada ≤4°C, agitar antes del servicio para recuperar emulsión uniforme y preservar aroma frutal y especiado', '[{"n": "Maracuya", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 500.0, "und": "ml", "costo": 4111.91}, {"n": "Vinagre Blanco", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "ml", "cant": 700.0, "und": "ml", "costo": 2029.94575}, {"n": "Aceite Vegetal", "detalle": "o escencia de coco", "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 300.0, "und": "gr", "costo": 3134.277}, {"n": "Azucar", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 180.0, "und": "gr", "costo": 510.7644}, {"n": "Mostaza", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 60.0, "und": "gr", "costo": 874.8504878}, {"n": "Sal", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 15.0, "und": "gr", "costo": 42.972}, {"n": "Jengibre En Polvo", "detalle": null, "presentacion": 1000.0, "presentacion_unidad": "gr", "cant": 50.0, "und": "gr", "costo": 633.19}]'),
